"use strict";(self.webpackChunkintersect_product_website=self.webpackChunkintersect_product_website||[]).push([[6962],{2342:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>h,frontMatter:()=>o,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"product-research/elk-consortium/evidence-milestone-1/Milestone-1-adjacent-ecosystems-benchmark","title":"Adjacent Ecosystem Benchmark","description":"A Vertical Approach for Cardano \\\\- Vertical-to-KPI Impact Framework","source":"@site/docs/product-research/elk-consortium/evidence-milestone-1/Milestone-1-adjacent-ecosystems-benchmark.md","sourceDirName":"product-research/elk-consortium/evidence-milestone-1","slug":"/product-research/elk-consortium/evidence-milestone-1/Milestone-1-adjacent-ecosystems-benchmark","permalink":"/product-research/elk-consortium/evidence-milestone-1/Milestone-1-adjacent-ecosystems-benchmark","draft":false,"unlisted":false,"editUrl":"https://github.com/IntersectMBO/product-website/edit/master/docs/product-research/elk-consortium/evidence-milestone-1/Milestone-1-adjacent-ecosystems-benchmark.md","tags":[],"version":"current","frontMatter":{"title":"Adjacent Ecosystem Benchmark","sidebar_label":"Ecosystem Benchmark"},"sidebar":"docsSidebar","previous":{"title":"KPI Synthesis and Audit","permalink":"/product-research/elk-consortium/evidence-milestone-1/Milestone-1-2030-KPI-synthesis-and-ecosystem-audit"},"next":{"title":"Impact Vertical Template","permalink":"/product-research/elk-consortium/evidence-milestone-1/Milestone-1-impact-vertical-chain-template"}}');var i=t(4848),r=t(8453);const o={title:"Adjacent Ecosystem Benchmark",sidebar_label:"Ecosystem Benchmark"},a="Phase 1 - Part 3: Benchmark: Coordinated BD, Strategy & Funding Across Leading Blockchain Ecosystems",l={},c=[{value:"A Vertical Approach for Cardano - Vertical-to-KPI Impact Framework",id:"a-vertical-approach-for-cardano---vertical-to-kpi-impact-framework",level:2},{value:"<strong>2.1 Polkadot - A Comparable Decentralized On-Chain Governance Model</strong>",id:"21-polkadot---a-comparable-decentralized-on-chain-governance-model",level:2},{value:"<strong>2.2 Cosmos - Sovereignty Without Coordination</strong>",id:"22-cosmos---sovereignty-without-coordination",level:2},{value:"<strong>3.1 XRP / XRP Ledger (Ripple)</strong>",id:"31-xrp--xrp-ledger-ripple",level:2},{value:"<strong>3.2 Solana</strong>",id:"32-solana",level:2},{value:"<strong>3.3 Ethereum</strong>",id:"33-ethereum",level:2},{value:"<strong>3.4 Avalanche</strong>",id:"34-avalanche",level:2},{value:"<strong>3.5 Polygon</strong>",id:"35-polygon",level:2}];function d(e){const n={br:"br",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"phase-1---part-3-benchmark-coordinated-bd-strategy--funding-across-leading-blockchain-ecosystems",children:(0,i.jsx)(n.strong,{children:"Phase 1 - Part 3: Benchmark: Coordinated BD, Strategy & Funding Across Leading Blockchain Ecosystems"})})}),"\n",(0,i.jsx)(n.h2,{id:"a-vertical-approach-for-cardano---vertical-to-kpi-impact-framework",children:"A Vertical Approach for Cardano - Vertical-to-KPI Impact Framework"}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Executive Summary:"})," This document benchmarks how six leading blockchain ecosystems, Polkadot, Cosmos, XRP, Solana, Ethereum, Avalanche, and Polygon, actually operate across three consistent analytical lenses: strategic focus, coordinated business development, and funding discipline. The findings directly inform how the Cardano Vertical-to-KPI Impact Framework is structured to impose strategic accountability without sacrificing decentralization."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Project:"})," A Vertical Approach for Cardano \u2014 Vertical-to-KPI Impact Framework",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"Author:"})," Benjamin Ben Zvi - ELK GmBh",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"Document Type:"})," Phase 1 Foundational Research (Covers Proposal Tasks P1-1 and P1-2)",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"Release Date:"})," August 2026"]}),"\n",(0,i.jsx)(n.h1,{id:"table-of-contents",children:(0,i.jsx)(n.strong,{children:"Table of Contents"})}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsx)(n.li,{children:"Introduction"}),"\n",(0,i.jsxs)(n.li,{children:["Decentralized, Governance-Led Models",(0,i.jsx)(n.br,{}),"\n","2.1Polkadot - A Comparable Decentralized On-Chain Governance Model",(0,i.jsx)(n.br,{}),"\n","2.2 Cosmos - Sovereignty Without Coordination"]}),"\n",(0,i.jsxs)(n.li,{children:["More Centrally Coordinated Ecosystems",(0,i.jsx)(n.br,{}),"\n","3.1 XRP / XRP Ledger (Ripple)",(0,i.jsx)(n.br,{}),"\n","3.2 Solana",(0,i.jsx)(n.br,{}),"\n","3.3 Ethereum",(0,i.jsx)(n.br,{}),"\n","3.4 Avalanche",(0,i.jsx)(n.br,{}),"\n","3.5 Polygon"]}),"\n",(0,i.jsx)(n.li,{children:"Cross-Ecosystem Comparative Summary"}),"\n",(0,i.jsx)(n.li,{children:"What This Research Tells Us"}),"\n",(0,i.jsx)(n.li,{children:"Conclusion"}),"\n"]}),"\n",(0,i.jsx)(n.h1,{id:"1-introduction",children:(0,i.jsx)(n.strong,{children:"1. Introduction"})}),"\n",(0,i.jsx)(n.p,{children:"This benchmark studies how leading blockchain ecosystems actually operate along three consistent analytical lenses:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus:"}),' Is there a clear, identifiable strategic direction (what the chain is "for"), or is direction diffuse and emergent?']}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Coordinated BD:"})," How do the companies, foundations, and teams inside each ecosystem work together, and what actually produces (or prevents) that coordination?"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Funding & the vision-filter:"})," How are initiatives funded, and, more importantly, is there a clear strategic logic guiding what gets backed, rather than funding everything that applies?"]}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:["The order of this document is deliberate. We begin with the two ecosystems structurally closest to Cardano, ",(0,i.jsx)(n.strong,{children:"Polkadot"})," and ",(0,i.jsx)(n.strong,{children:"Cosmos"}),", because they share Cardano's defining trait: direction and funding flow through decentralized, on-chain, token-holder governance rather than a single controlling company. Studying them is effectively studying our own model's strengths and failure modes. We then examine a set of more centrally coordinated ecosystems, ",(0,i.jsx)(n.strong,{children:"XRP, Solana, Ethereum, Avalanche,"})," and ",(0,i.jsx)(n.strong,{children:"Polygon"}),", that offer useful contrasts on strategy and coordination."]}),"\n",(0,i.jsx)(n.p,{children:"For each ecosystem we also assess whether the approach is working and note institutions that have joined recently, where information is available. Figures move quickly in this industry; treat all quantitative points as time-stamped snapshots rather than fixed facts. Sources are referenced inline throughout the document."}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Research Scope & Analytical Method:"}),' Each ecosystem is assessed across the same three lenses (Strategy & Focus, Coordinated BD, Funding & Vision-Filter) and a fourth question, "Is it working?", measured via institutional adoption, on-chain metrics, and market position as of August 2026. This structure ensures cross-ecosystem comparability and prevents cherry-picking.']}),"\n",(0,i.jsx)(n.h1,{id:"2-ecosystems-closest-to-cardano-decentralized-governance-led-models",children:(0,i.jsx)(n.strong,{children:"2. Ecosystems Closest to Cardano: Decentralized, Governance-Led Models"})}),"\n",(0,i.jsx)(n.p,{children:"These two ecosystems matter most to this research because they share Cardano's defining trait: there is no single company that dictates strategy. Direction and funding flow through on-chain, token-holder governance, structurally the same problem Cardano faces with Catalyst and DReps."}),"\n",(0,i.jsx)(n.h2,{id:"21-polkadot---a-comparable-decentralized-on-chain-governance-model",children:(0,i.jsx)(n.strong,{children:"2.1 Polkadot - A Comparable Decentralized On-Chain Governance Model"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"GOVERNANCE MODEL:"})," ON-CHAIN OPENGOV",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"COORDINATION STRUCTURE"}),": DELEGATED CURATORS & DEPARTMENTS",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"STRATEGIC FOCUS:"})," INTEROPERABILITY & SHARED SECURITY"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus."}),' Shared security via parachains, evolving toward a more flexible "agile coretime" model for buying blockspace. Strategically focused on interoperability and pooled security.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"How it works (sharing similarities to Cardano\u2019s governance system)."}),' Polkadot runs OpenGov: any DOT holder can submit a treasury proposal and any DOT holder can vote, with no company or foundation approval required. Proposals are sorted into 15 "tracks" by size and privilege (from Small Tipper up to Big Spender and Treasurer), each with its own voting duration and thresholds. Token holders can also delegate their vote track-by-track to trusted experts, e.g. a technical delegate for protocol upgrades, a treasury-focused delegate for spending.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:'The "vision filter" problem, made concrete.'})," Polkadot is the clearest real-world evidence of the exact risk this project is trying to solve. OpenGov distributes decision-making widely but historically lacked a shared strategic test for what deserves funding, producing:"]}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Spend outpacing income for most of OpenGov's history"})," - the treasury ran a deficit for years."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:'"Sponsorship fatigue"'})," - after a year of funding racing, football, and esports deals, a flagship 1.5M DOT (~$5M) esports proposal was rejected with a near-100% disapproval rate, as holders openly questioned measurable ROI. (OpenGov.Watch, Apr 2025)"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Large asks with weak deliberation"}),' - a 5M DOT (~$25M, ~18% of the treasury) liquidity-incentive request drew criticism that incentive-driven growth had "no convincing long-term model." (OpenGov.Watch, Apr 2025)']}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"How they're fixing it (directly relevant to us)."})," Polkadot's 2025\u20132026 reforms are essentially attempts to bolt a vision filter and accountability layer onto an open voting system:"]}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Bounties + curators + departments:"})," Rather than funding every line item by mass vote, the treasury delegates budgets to accountable curators/departments with scoped mandates and forfeitable deposits. By Q4 2025, a record 68% of spending flowed through these delegated structures rather than one-off votes. (CryptoNews)"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Dynamic Allocation Pool (DAP),"})," from March 2026: Replaced the old burn-based model to put treasury inflows under deliberate governance allocation across staking, treasury, and a strategic reserve. (BSCN)"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Result:"})," Q4 2025 was the treasury's first-ever net surplus under OpenGov (spend down to $7.4M, its lowest quarter), evidence that spending discipline improved, even as DOT's price kept falling ($0.80\u20130.88, down ~52% YTD by Aug 2026). (CryptoNews)"]}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Takeaway for Cardano"}),(0,i.jsx)(n.br,{}),"\n",'Polkadot shows that decentralized treasuries can impose discipline, but only by adding delegated, accountable, mandate-scoped bodies (curators/departments) on top of raw voting. Pure "anyone proposes, everyone votes" without a strategic filter reliably produces scattered, ROI-poor spending. This is arguably the single most useful precedent for how a Cardano vertical framework could sit between DReps and vertical work.']}),"\n",(0,i.jsx)(n.h2,{id:"22-cosmos---sovereignty-without-coordination",children:(0,i.jsx)(n.strong,{children:"2.2 Cosmos - Sovereignty Without Coordination"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"GOVERNANCE MODEL:"})," ON-CHAIN HUB GOVERNANCE",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"COORDINATION STRUCTURE:"})," FRAGMENTED; NOW COSMOS LABS",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"STRATEGIC FOCUS:"})," SOVEREIGNTY & INTEROPERABILITY"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus."}),' An "internet of blockchains" built on sovereignty and interoperability, app-chains connected via IBC. Rather than defining a single ecosystem-level focus, the architecture delegates strategic direction to each sovereign chain.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Business development and industry verticals"}),". Commercial development has historically been the responsibility of individual sovereign chains rather than a Hub-level programme. Each zone, Osmosis, Injective, dYdX, manages its own partnerships and BD independently. Cosmos Labs has begun to address this in 2025\u20132026, pivoting toward enterprise outreach in financial services, CBDCs, and tokenised deposits; however, this remains largely at the infrastructure and stack level, and there is not yet a coordinated industry-vertical strategy operating at the Hub or ATOM ecosystem level comparable to what Cardano is building."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"How it works."}),' Cosmos is a "hub-and-zone" model: the Cosmos Hub coordinates, but each connected chain (Osmosis, Injective, dYdX, Celestia, etc.) is fully sovereign, own validators, own token, own governance. The Hub itself uses on-chain ATOM governance for upgrades, parameters, and community-pool spending. IBC now connects 115+ chains. (CoinStats Fundamental Analysis, Aug 2026; CoinEx Academy)']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"The core failure - value and strategy fragment."})," Cosmos is the industry's clearest example of excellent technology undermined by lack of coordination:"]}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["Its founding philosophy of sovereignty meant ",(0,i.jsx)(n.strong,{children:"value flowed to individual chains, not to ATOM or the Hub"}),", dYdX, Osmosis, and Injective all built on Cosmos tech without routing value back. (CoinEx Academy)"]}),"\n",(0,i.jsx)(n.li,{children:"Governance fragmented and development slowed; Cosmos Hub TVL reportedly collapsed to a fraction of its 2024 peak, and ATOM sits ~95%+ below its 2022 high. (Simply Staking, Dec 2025; CoinStats)"}),"\n",(0,i.jsx)(n.li,{children:"Founder-level philosophical splits (Jae Kwon's AtomOne fork over governance direction) illustrate how far the coordination problem went. (CoinStats)"}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"The fix - re-introducing central coordination."})," Tellingly, Cosmos's 2025\u20132026 turnaround is a",(0,i.jsx)(n.br,{}),"\n","deliberate move away from pure decentralized stewardship:",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"Cosmos Labs"}),' (formed 2025 after the Interchain Foundation acquired the Skip team) is now a central engineering/product team giving the Hub "structured execution" instead of diffuse stewardship, and has shipped IBC v2/Eureka (bridge to Ethereum), Cosmos SDK v0.53, and the Cosmos EVM. (Simply Staking)']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Takeaway for Cardano"}),(0,i.jsx)(n.br,{}),"\n","Cosmos proves that sovereignty + interoperability + on-chain governance is not enough on its own, without a coordinating body and a shared value/strategy filter, a technically superb ecosystem fragments and underdelivers. Its own remedy was to re-centralize execution into Cosmos Labs."]}),"\n",(0,i.jsx)(n.h1,{id:"3-more-centrally-coordinated-ecosystems",children:(0,i.jsx)(n.strong,{children:"3. More Centrally Coordinated Ecosystems"})}),"\n",(0,i.jsx)(n.p,{children:"These ecosystems are not structured like Cardano, direction is set by a company or an actively convening foundation, but they offer valuable contrasts on how strategic focus and coordinated BD are produced."}),"\n",(0,i.jsx)(n.h2,{id:"31-xrp--xrp-ledger-ripple",children:(0,i.jsx)(n.strong,{children:"3.1 XRP / XRP Ledger (Ripple)"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"GOVERNANCE MODEL:"})," COMPANY-LED (RIPPLE)",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"COORDINATION:"})," TOP-DOWN, TIGHTLY ALIGNED",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"STRATEGIC FOCUS:"})," INSTITUTIONAL FINANCE & PAYMENTS"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus."}),' The clearest single-purpose strategy in the industry. Historically "low-cost, near-instant cross-border payments," it has broadened in 2026 into a deliberate, compliance-first push to become institutional financial infrastructure: payments, custody, stablecoin settlement (RLUSD), prime brokerage, and tokenization.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Coordinated BD."})," Coordination is company-led: Ripple sets direction and the ecosystem largely follows. Rather than relying on distributed community initiative, Ripple builds or acquires the pieces of the stack and integrates them, giving XRP a highly aligned, top-down BD model."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Funding & vision-filter."})," Ripple funds growth through direct investment and acquisition rather than an open community-grant vote, so there is a strong, explicit strategic filter, capital flows to the payments/institutional-finance thesis. Recent moves include the ~$1.25B Hidden Road acquisition (now Ripple Prime), the Rail and GTreasury acquisitions, and a $200M funding facility from Neuberger Berman to expand Ripple Prime."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Is it working?"})," A genuine split picture on the activity side. The ledger is generating meaningful on-chain volume: RLUSD recorded over $18B in transfer volume in Q1 2026 alone; XRPL added approximately $2.6B in tokenised RWA value in the six months to July 2026, ranking second among all chains for net RWA inflows and bringing total on-chain RWA value above $4B. Daily payment activity reached 2.6 million successful transactions by August 2026, with live corridors including SBI Remit (Japan\u2013Southeast Asia) and Bitso (USD\u2013MXN) citing 40\u201385% cost reductions versus traditional correspondent banking. Ripple\u2019s acquisition of Hidden Road, which facilitates approximately $3 trillion in annual volume, further anchors the institutional infrastructure thesis. The open question is how efficiently that on-chain activity converts into value accrual across the broader ecosystem, as institutional usage increasingly flows through RLUSD and company-intermediated rails rather than the native asset directly. (Sources: thecryptobasic.com, Yahoo Finance, Ripple Insights, 247wallst.com)"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Recent Institutional Entrants:"})," Securosys and Figment (custody), Chainalysis (compliance), SBI Holdings and Tranglo (APAC corridors), Mastercard (settlement integration), Franklin Templeton and Pantera (ecosystem investment), Aviva Investors (tokenization); wXRP launched on Solana via Hex Trust/LayerZero. ",(0,i.jsx)(n.strong,{children:"Sources:"})," KuCoin, IG, Seeking Alpha, AInvest, Unocoin, Bitcoin Foundation."]}),"\n",(0,i.jsx)(n.h2,{id:"32-solana",children:(0,i.jsx)(n.strong,{children:"3.2 Solana"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"GOVERNANCE MODEL:"})," FOUNDATION + TIGHT INFRASTRUCTURE CLUSTER",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"COORDINATION:"})," ACTIVE CONVENER",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"STRATEGIC FOCUS:"})," CONSUMER-SCALE ACTIVITY, STABLECOINS, DEPIN, RWA, AI COMMERCE"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus."}),' Multi-focus but coherent: a high-throughput, low-fee settlement layer for consumer-scale activity, stablecoin payments, DePIN, tokenized/real-world assets, and (increasingly) agentic/AI commerce. The 2026 framing is "internet capital markets" plus enterprise-grade reliability.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Coordinated BD."})," Coordination runs through the Solana Foundation plus a tight cluster of infrastructure companies (Jump Crypto/Firedancer, Anza, Helius, Jupiter). The Foundation actively orchestrates: e.g., launching coordinated security programs (STRIDE, SIRN) and even providing liquidity support during a cross-chain DeFi incident, behaving as an active convener rather than a passive steward."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Funding & vision-filter."})," Funded via Foundation grants, the Colosseum accelerator/hackathons (venture funding for startups), and heavy private VC. The filter is thematic, payments, DePIN, RWA, infrastructure, and increasingly tied to reliability standards (security funding scales with TVL)."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Is it working?"})," Strongly, on adoption metrics: ~3M+ daily active addresses, $14B+ stablecoin supply, $2.5B+ RWA value, 100% uptime through early 2026, Firedancer live (solving the client-diversity critique), and spot SOL ETFs attracting inflows. Main risks: protocol-level exploits and token-supply/emission pressure."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Recent Institutional Entrants:"})," SoFi, Shinhan Card, B2C2, Anchorage Digital, Singapore Gulf Bank, OCBC/Lion Global/DigiFT (tokenized gold), Coinbase Asset Management, Meta (USDC creator payments), MetaMask Card, Securitize, Alchemy, OVHcloud. ",(0,i.jsx)(n.strong,{children:"Sources:"})," Solana Foundation ecosystem roundup, Bitcoin Foundation, Phemex, AInvest."]}),"\n",(0,i.jsx)(n.h2,{id:"33-ethereum",children:(0,i.jsx)(n.strong,{children:"3.3 Ethereum"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"GOVERNANCE MODEL:"})," DELIBERATELY DECENTRALIZED; MULTIPLE BODIES",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"COORDINATION:"})," DISTRIBUTED AMICABLE DIVISION OF LABOUR",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"STRATEGIC FOCUS:"})," PROTOCOL STEWARDSHIP, ASSET ISSUANCE & SETTLEMENT"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus."})," Deliberately principle-led rather than product-led. In 2026 the Ethereum Foundation narrowed its mandate to protocol stewardship and neutrality under the CROPS framework (censorship resistance, open-source, privacy, security), while the Strawmap re-centred base-layer scaling. Its enduring strategic moat is asset issuance and settlement."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Coordinated BD."}),' The closest historical analogue to a central BD function was Consensys: founded by Joe Lubin in 2014, it incubated MetaMask (2016, now 100M+ users), Infura (2016, the dominant node-as-a-service provider, sometimes called the "AWS of Ethereum"), and helped launch the Enterprise Ethereum Alliance in 2017, bringing JPMorgan, Microsoft, and hundreds of enterprises into the ecosystem. The 2020 acquisition of J.P. Morgan\u2019s Quorum further extended enterprise reach. In this sense Consensys played a role analogous to EMURGO for Cardano, a commercially-oriented arm driving institutional BD while the foundation focused on protocol development.']}),"\n",(0,i.jsx)(n.p,{children:'By 2026, however, this model had been explicitly unwound. The EF cut ~20% of staff and ~40% of budget and pushed adoption and BD out to a constellation of independent bodies, EthLabs, Ethereum Institutional, EthSystems, the Applications Guild, Etherealize. Coordination is now an "amicable division of labor" across many organizations rather than one hub, powerful for neutrality, but with acknowledged risk of competing factions.'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Funding & vision-filter."}),' Public-goods funding, grants, and now separately-funded spinouts (backed by ETH treasury companies like BitMine and SharpLink, plus Consensys\' Joe Lubin). The EF explicitly refuses to optimize for token price; the "vision filter" is principle-based (does it advance CROPS) rather than commercial.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Is it working?"})," Mixed. Trust of capital remains, ~half of stablecoin supply, a slim majority of RWAs (absolute RWA value up 12x), $11B+ cumulative spot-ETF inflows, and deepening BlackRock/JPMorgan involvement. But it has lost user attention and market share: DEX volume share fell from ~68% to ~20%, fee share to ~10%, and ETH/BTC sits far below its 2022 Merge level. The 2026 reorg is the bet to close that gap."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Recent Entrants / Actors:"})," BlackRock (staked-ETH ETFs, DeFi), JPMorgan (settlement), plus new institutions EthLabs, Ethereum Institutional, and EthSystems. ",(0,i.jsx)(n.strong,{children:"Sources:"})," Galaxy Research, CoinDesk \u2013 EF timeline, CoinDesk \u2013 second decade."]}),"\n",(0,i.jsx)(n.h2,{id:""}),"\n",(0,i.jsx)(n.h2,{id:"34-avalanche",children:(0,i.jsx)(n.strong,{children:"3.4 Avalanche"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"GOVERNANCE MODEL:"})," FOUNDATION-LED",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"COORDINATION:"})," ACTIVE FOUNDATION CONVENER",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"STRATEGIC FOCUS:"})," SOVEREIGN L1S, INSTITUTIONAL RWA & GAMING"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus."}),' A "subnets / custom L1s + institutional/RWA + gaming" thesis that is now precise: Avalanche9000 / Etna (Dec 16, 2024) renamed subnets to sovereign L1s and cut deployment cost ~99% (flat ~1.33 AVAX/validator/month). (Eco.com explainer, Bitcoin Foundation)']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Funding & vision-filter."})," Retro9000, up to 40M AVAX in retroactive grants to L1 builders; the older Avalanche Rush committed up to $180M in DeFi incentives; a $200M ecosystem VC fund. Filter targets institutional/RWA/gaming. (CoinStats fundamental analysis)"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Is it working?"})," Institutional traction is strong and measurable, RWA value at ~$1.1B, with active inroads into regulated financial markets and gaming through specific enterprise pilots."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Recent Institutional Entrants:"})," JPMorgan Onyx, Citi, Franklin Templeton, Hamilton Lane, T. Rowe Price, WisdomTree; POSCO (tokenized trade receivables, Aug 2026); Japan FSA/BoJ studying Avalanche for settlement; Progmat migrated \xa5452B tokenized securities; FIFA World Cup 2026 ticketing; CME AVAX futures. ",(0,i.jsx)(n.strong,{children:"Sources:"})," CoinMarketCap AVAX news, Criptolog."]}),"\n",(0,i.jsx)(n.h2,{id:"35-polygon",children:(0,i.jsx)(n.strong,{children:"3.5 Polygon"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"GOVERNANCE MODEL:"})," COMPANY-LED (POLYGON LABS)",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"COORDINATION:"})," ENTERPRISE-FILTERED, TOP-DOWN",(0,i.jsx)(n.br,{}),"\n",(0,i.jsx)(n.strong,{children:"STRATEGIC FOCUS:"})," PAYMENTS & RWA SETTLEMENT LAYER"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Strategy & focus."}),' The "repeated pivots" critique now resolves into one sharp thesis: the payments + RWA settlement layer ("Open Money Stack," Gigagas roadmap to 100k TPS). (Polygon Gigagas blog, Polygon \u2013 "Bringing enterprises onchain")']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Funding & vision-filter."})," $250M acquisitions (Coinme + Sequence) to own fiat on-ramps; Agglayer Breakout Program airdrops; protocol-fee subsidies (e.g. $1M earmarked for x402/agent payments). Company-led, enterprise-filtered. (PANews, Crypto News Navigator)"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Is it working?"})," Payment volumes are compelling at scale, Polygon reportedly settled 54% of global USDC transfers ($14B/month) in April 2026. Enterprise partnerships are accumulating rapidly around the payments and stablecoin settlement thesis."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Recent Institutional Entrants:"})," Stripe, Visa (settlement program), Mastercard (Agent Pay founding partner), Meta (creator USDC payouts), Revolut (EURR stablecoin), Shift4, Paxos, Cash App, BlackRock (BUIDL), Franklin Templeton, Polymarket, NRW.BANK, Bank of England Digital Pound Lab Phase 2. ",(0,i.jsx)(n.strong,{children:"Sources:"})," Crypto News Navigator, Polygon blog."]}),"\n",(0,i.jsx)(n.h1,{id:"4-cross-ecosystem-comparative-summary",children:(0,i.jsx)(n.strong,{children:"4. Cross-Ecosystem Comparative Summary"})}),"\n",(0,i.jsx)(n.p,{children:"The table below consolidates findings across all seven ecosystems for rapid side-by-side comparison. Each is assessed across the three analytical lenses plus an outcome verdict."}),"\n",(0,i.jsxs)(n.table,{children:[(0,i.jsx)(n.thead,{children:(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.th,{children:"Ecosystem"}),(0,i.jsx)(n.th,{children:"Governance Model"}),(0,i.jsx)(n.th,{children:"Strategic Focus"}),(0,i.jsx)(n.th,{children:"BD Coordination"}),(0,i.jsx)(n.th,{children:"Vision Filter"}),(0,i.jsx)(n.th,{children:"Outcome Verdict"})]})}),(0,i.jsxs)(n.tbody,{children:[(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.td,{children:(0,i.jsx)(n.strong,{children:"Polkadot"})}),(0,i.jsx)(n.td,{children:"On-Chain OpenGov"}),(0,i.jsx)(n.td,{children:"Interoperability & shared security (agile coretime)"}),(0,i.jsx)(n.td,{children:"Delegated curators / departments from Q4 2025"}),(0,i.jsx)(n.td,{children:"Historically weak; now strengthening via DAP & mandated curators"}),(0,i.jsx)(n.td,{children:"Improving \u2014 first treasury surplus Q4 2025; price still falling"})]}),(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.td,{children:(0,i.jsx)(n.strong,{children:"Cosmos"})}),(0,i.jsx)(n.td,{children:"On-Chain Hub Gov"}),(0,i.jsx)(n.td,{children:"Sovereignty + IBC interoperability (multi-chain)"}),(0,i.jsx)(n.td,{children:"Historically fragmented; now Cosmos Labs central team"}),(0,i.jsx)(n.td,{children:"Absent; being retrofitted via tokenomics & Cosmos Labs mandate"}),(0,i.jsx)(n.td,{children:"Turnaround underway; ATOM far below 2022 high"})]}),(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.td,{children:(0,i.jsx)(n.strong,{children:"XRP (Ripple)"})}),(0,i.jsx)(n.td,{children:"Company-Led"}),(0,i.jsx)(n.td,{children:"Institutional finance & cross-border payments"}),(0,i.jsx)(n.td,{children:"Top-down, Ripple builds/acquires the stack"}),(0,i.jsx)(n.td,{children:"Strong \u2014 payments/institutional thesis filters all capital"}),(0,i.jsx)(n.td,{children:"Strong institutional traction; XRP token demand lagging"})]}),(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.td,{children:(0,i.jsx)(n.strong,{children:"Solana"})}),(0,i.jsx)(n.td,{children:"Foundation + Infra Cluster"}),(0,i.jsx)(n.td,{children:"Consumer scale, stablecoins, DePIN, RWA, AI"}),(0,i.jsx)(n.td,{children:"Foundation as active convener + tight infra cluster"}),(0,i.jsx)(n.td,{children:"Thematic (payments/DePIN/RWA) + reliability standards"}),(0,i.jsx)(n.td,{children:"Strongest on adoption metrics; exploit risk remains"})]}),(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.td,{children:(0,i.jsx)(n.strong,{children:"Ethereum"})}),(0,i.jsx)(n.td,{children:"Principle-Led Multi-Body"}),(0,i.jsx)(n.td,{children:"Protocol stewardship, asset issuance & settlement"}),(0,i.jsx)(n.td,{children:"Amicable division of labour; decentralized by design"}),(0,i.jsx)(n.td,{children:"Principle-based (CROPS); no commercial filter"}),(0,i.jsx)(n.td,{children:"Capital trust strong; user share declining; 2026 reorg is the bet"})]}),(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.td,{children:(0,i.jsx)(n.strong,{children:"Avalanche"})}),(0,i.jsx)(n.td,{children:"Foundation-Led"}),(0,i.jsx)(n.td,{children:"Sovereign L1s, institutional RWA & gaming"}),(0,i.jsx)(n.td,{children:"Foundation + VC ecosystem investment programs"}),(0,i.jsx)(n.td,{children:"Strong \u2014 institutional/RWA/gaming thesis drives grants"}),(0,i.jsx)(n.td,{children:"Growing institutional base; ~$1.1B RWA on-chain"})]}),(0,i.jsxs)(n.tr,{children:[(0,i.jsx)(n.td,{children:(0,i.jsx)(n.strong,{children:"Polygon"})}),(0,i.jsx)(n.td,{children:"Company-Led"}),(0,i.jsx)(n.td,{children:"Payments + RWA settlement (\u201cOpen Money Stack\u201d)"}),(0,i.jsx)(n.td,{children:"Top-down; enterprise-targeted; fee subsidies"}),(0,i.jsx)(n.td,{children:"Strong \u2014 enterprise payments thesis filters spending"}),(0,i.jsx)(n.td,{children:"54% global USDC settlement; major enterprise pipeline"})]})]})]}),"\n",(0,i.jsx)(n.h1,{id:"5-what-this-research-tells-us",children:(0,i.jsx)(n.strong,{children:"5. What This Research Tells Us"})}),"\n",(0,i.jsx)(n.p,{children:"Looking across these ecosystems as neutral observations, six cross-cutting findings emerge:"}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsx)(n.li,{children:"The models closest to Cardano converge on one lesson. Polkadot and Cosmos, the only two here that fund and steer through decentralized, on-chain governance, both discovered that token-holder voting delivers legitimacy but not strategy. Both are now bolting on a coordinating layer: Polkadot via accountable curators/departments/bounties, Cosmos via a central execution team (Cosmos Labs). Neither relied on voters spontaneously becoming strategic."}),"\n",(0,i.jsx)(n.li,{children:"Coordination almost always comes from a central company or foundation. The most tightly aligned ecosystems (XRP/Ripple, Polygon Labs) are effectively company-led. The most decentralized (Cosmos, and historically Ethereum) achieve neutrality but struggle with fragmented, slow, or diffuse BD. Ethereum's 2026 reorganization is a live experiment in deliberately distributing coordination across many aligned organizations rather than one hub."}),"\n",(0,i.jsx)(n.li,{children:"A clear one-line focus is rarer than it looks, and doesn't have to be singular. Only a handful can state their purpose in a sentence (XRP: cross-border/institutional finance). Most successful larger ecosystems (Solana, Ethereum) run multiple coherent focuses held together by a strong central convener, evidence that multi-vertical breadth and strategic legibility can coexist when coordination exists."}),"\n",(0,i.jsx)(n.li,{children:'A genuine "vision filter" on funding is uncommon. Company-led chains filter capital tightly toward their thesis. Governance/treasury-led models (Polkadot\'s OpenGov; Cosmos community pools) historically fund broadly but lack a shared strategic test for what deserves backing, the recurring weakness being funding activity without clear linkage to defined outcomes.'}),"\n",(0,i.jsx)(n.li,{children:'"Is it working?" splits along a revealing line. Ecosystems with a clear focus and a coordinating body are converting into institutional adoption (XRP ledger, Solana). Those rich in technology but poor in coordination underdeliver relative to their capability (Cosmos; arguably Polkadot before its recent reforms). Even Ethereum\'s challenge is framed as coordination and focus, not technology.'}),"\n",(0,i.jsx)(n.li,{children:"Recent institutional entrants cluster around the coordinated, focused chains. Banks, card issuers, custodians, and asset managers are joining XRP, Solana, Ethereum, Avalanche, and Polygon, itself a signal that external partners gravitate to ecosystems where strategy and points of contact are legible."}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Implication for the Vertical-to-KPI Framework"}),(0,i.jsx)(n.br,{}),"\n","The patterns above are not coincidental. They suggest that the Cardano ecosystem's challenge is not technical, it is structural and coordination-based. The six findings directly inform the design requirements of the P1-4 Impact Vertical Chain, Scenario Modeling Engine, and Vertical Impact Scorecard: each component is calibrated to solve a specific failure mode surfaced by this comparative research."]}),"\n",(0,i.jsx)(n.h1,{id:"6-conclusion",children:(0,i.jsx)(n.strong,{children:"6. Conclusion"})}),"\n",(0,i.jsx)(n.p,{children:'Across the industry, strategic focus and coordinated BD are produced structurally, by a company, a foundation acting as an active convener, or (rarely) by an exceptionally strong shared culture. Broad, well-funded, governance-led ecosystems tend to lack the shared "vision filter" that turns activity into outcomes.'}),"\n",(0,i.jsx)(n.p,{children:"The two ecosystems that mirror Cardano most closely, Polkadot and Cosmos, make this concrete. Both proved that decentralized, on-chain funding is excellent for legitimacy but fails at strategy unless a filtering and coordinating layer is added, and, critically, both fixed it with structural mechanisms (curators/departments; a central execution team), not by hoping voters would self-coordinate."}),"\n",(0,i.jsx)(n.p,{children:"This is precisely the gap the Vertical-to-KPI framework targets. A \"Vertical Lead\" with a scoped mandate, a thesis linking activity to the 2030 KPIs, and accountable reporting is essentially Cardano's version of Polkadot's curator/department model, a vision filter sitting between DRep voting and vertical execution, without sacrificing decentralization. Polkadot and Cosmos show both the cost of not having such a layer and the shape of the solution."})]})}function h(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>o,x:()=>a});var s=t(6540);const i={},r=s.createContext(i);function o(e){const n=s.useContext(r);return s.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),s.createElement(r.Provider,{value:n},e.children)}}}]);